window.RP_SESSION={"id":"S-da122ca6fd11","messages":[{"id":"RP-0017361","time":"2026-01-16T23:47:00+09:00","room":"RP","name":"은발의 소녀 (이름 미확인)","profile":"델타인","identity":"reviewed","type":"dialogue","body":"만들어진 지 얼마 되지 않은 삐뚤빼뚤한 강이 광활한 대지 위를 누비면, 그 옆에는 드문드문 자라있는 자작나무와 낙엽송은 골짜기를 타고 흐르는 거센 바람에 비질하는 소리를 냈다.\n\n눈이 시리도록 푸른 하늘을 찌르는 산꼭대기는 모자처럼 만년설을 얹고, 산줄기를 따라 길들지 않은 비탈길에는 야생 염소들이 뛰놀고 있었다.\n\n신을 믿지 않는 사람도 신을 찬미하게 될 자연의 장엄함 속에 키가 작은 여자가 서 있다. 성숙한 분위기와는 달리 외관은 막 성인이 된 듯, 숙녀라기 보다는 소녀라는 표현이 어울리는 앳된 외모.\n\n다만 누구든 그녀를 처음 본 사람이라면 그 사실을 알아차리기까지 조금 시간이 걸릴 것이다. 소녀의 체모와 눈동자가 산맥의 자연경관 이상으로 신비롭기 때문이다.\n\n연한 은빛의 탐스러운 장발과 자홍색의 눈동자는 사람을 홀리는 여우의 것처럼 요사스럽다. 요사스러운 것은 소녀의 외모뿐만이 아니다.\n\n이곳은 전통 유목민들의 거주지까지 직선거리로 수십 킬로미터는 나아가야 하는 험지이다. 한","characters":[]},{"id":"RP-0017362","time":"2026-01-17T00:11:00+09:00","room":"RP","name":"은발의 소녀 (이름 미확인)","profile":"델타인","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-0017363","time":"2026-01-17T00:12:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
